package com.tapin.notifications.push;

import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.boot.context.properties.bind.DefaultValue;

import java.net.URI;
import java.time.Duration;
import java.util.List;
import java.util.Locale;

/**
 * Web push ({@code tapin.push.*}). Push is switched on only when both VAPID keys are set (environment variables
 * {@code VAPID_PUBLIC_KEY} / {@code VAPID_PRIVATE_KEY}, generated by {@code scripts/generate-vapid-keys.mjs}); without
 * them member notifications remain available in the inbox.
 *
 * @param vapidPublicKey  application server key: uncompressed P-256 point, base64url (65 bytes)
 * @param vapidPrivateKey the private scalar d, base64url (32 bytes); a secret, never committed
 * @param vapidSubject    contact for push services ({@code mailto:} or {@code https:} URL), RFC 8292
 * @param allowedHosts    push service host suffixes a subscription endpoint may point to; the server POSTs to that
 *                        URL, so arbitrary hosts are refused (no request forgery towards internal addresses)
 * @param timeout         connect and request timeout towards the push service (well below the outbox lease)
 */
@ConfigurationProperties(prefix = "tapin.push")
public record PushProperties(
        String vapidPublicKey,
        String vapidPrivateKey,
        @DefaultValue("mailto:no-reply@tapin.local") String vapidSubject,
        @DefaultValue({"fcm.googleapis.com", "push.services.mozilla.com", "push.apple.com", "notify.windows.com"})
        List<String> allowedHosts,
        @DefaultValue("10s") Duration timeout) {

    public boolean enabled() {
        return vapidPublicKey != null && !vapidPublicKey.isBlank()
                && vapidPrivateKey != null && !vapidPrivateKey.isBlank();
    }

    /** HTTPS and a host equal to, or a subdomain of, one of {@link #allowedHosts}. */
    public boolean isAllowedEndpoint(String endpoint) {
        URI uri;
        try {
            uri = URI.create(endpoint);
        } catch (IllegalArgumentException e) {
            return false;
        }
        if (!"https".equalsIgnoreCase(uri.getScheme()) || uri.getHost() == null || uri.getUserInfo() != null) {
            return false;
        }
        String host = uri.getHost().toLowerCase(Locale.ROOT);
        return allowedHosts.stream().map(h -> h.toLowerCase(Locale.ROOT))
                .anyMatch(allowed -> host.equals(allowed) || host.endsWith("." + allowed));
    }
}
